import Foundation
import Testing
import VideoToolbox
import WebcamBridge
import WebcamCore
@testable import WebcamProbe
import WebcamTestSupport

// Defect 177, option A — old against new RELEASE decode probes on the SAME generated bytes, with the
// scenarios, pacing and repetition count fixed here BEFORE any run (so no scenario was chosen after
// seeing which one flattered the change). Opt-in and never part of the ordinary suite:
//
//   COMPARE_PROBES="old=/path/a,new=/path/b"   the binaries, each built with
//                                                `swift build -c release --scratch-path <dir>` — never into
//                                                `.build/release`, which the dev Mac resolves
//   COMPARE_OUT=/path/result.json               where the integers go
//
// It REPORTS and never asserts a timing: it measures this Mac, under whatever else is running, on
// generated pictures that are far simpler to decode than a camera's. The only assertions are that each
// run ended (exit 0, the invariant line present) — an instrument that did not finish has no reading.

private let REPETITIONS = 10                       // per scenario, per binary — fixed before the first run
private let FRAME_US: UInt64 = 33_333
private let LIMIT_SECONDS = 30                     // the probe's own --max-seconds, and the harness's kill
private let A = SESSION
private let B = SessionID(hex: "ffeeddccbbaa99887766554433221100")!

/// One write to the probe's stdin, `atUs` after the run's first write.
struct ComparisonWrite { let atUs: UInt64; let bytes: Data }

private func control(_ m: ControlMessage) -> Data {
    BridgeRecord.encode(BridgeRecord(type: .control, body: ControlCodec.encode(m)))
}
private func record(_ s: SessionID, _ frame: Data) -> Data {
    BridgeRecord.encode(BridgeRecord(type: .accessUnit, body: ControlCodec.accessUnitBody(session: s, frame: frame)))
}

/// The scenarios, all generated 1080p High (A) with an IDR every 60 frames, wrapped by the phone stand-in.
enum ComparisonScenario: String, CaseIterable {
    /// `session-live` with the first AU, then one AU every 33.3 ms.
    case smooth = "smooth-1080p"
    /// `session-live` and AUs 0–16 in ONE write — how main flushes what it held before `running` — then
    /// paced. The shape that reproduced the field's signature on 2026-10-04.
    case startupBurst = "startup-burst-17-in-one-write"
    /// `session-live`, then AUs 0–16 every 16.7 ms (twice the frame rate), then paced.
    case startupBurstSpread = "startup-burst-17-at-2x"
    /// Paced to AU 59, then AUs 60–76 (the second GOP's IDR and 16 more) in one write, then paced.
    case laterGOPBurst = "later-gop-burst-17-in-one-write"
    /// `session-live`, the IDR, three P-frames and `session-ended` in ONE write: the Stop lands while
    /// the session is preparing and its first frame decoding. Then a second session is announced and
    /// stopped in one write with no AU at all.
    case stopWhilePreparing = "stop-while-preparing-and-decoding"
    /// Session A (1080p, rotation 1) for 60 AUs; then B replaces it in one write with B's first 6 AUs
    /// (720p, rotation 0, a different size and turn), then B paced for 54 more, then B ends.
    case replacement = "replacement-changing-size-and-rotation"

    func writes(fullHD: [Data], hd: [Data]) -> [ComparisonWrite] {
        var phone = PhoneStandIn()
        phone.rotation = 1
        let wrap = { (s: SessionID, i: Int) -> Data in record(s, phone.frame(annexB: fullHD[i], width: 1920, height: 1080)) }
        let live = control(.sessionLive(A, generation: 1))
        let end = control(.sessionEnded(A, reason: "stopped-by-mac"))
        var w: [ComparisonWrite] = []
        switch self {
        case .smooth:
            w.append(ComparisonWrite(atUs: 0, bytes: live + wrap(A, 0)))
            for i in 1..<150 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US, bytes: wrap(A, i))) }
            w.append(ComparisonWrite(atUs: 150 * FRAME_US, bytes: end))
        case .startupBurst:
            w.append(ComparisonWrite(atUs: 0, bytes: (0...16).reduce(live) { $0 + wrap(A, $1) }))
            for i in 17..<150 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US, bytes: wrap(A, i))) }
            w.append(ComparisonWrite(atUs: 150 * FRAME_US, bytes: end))
        case .startupBurstSpread:
            w.append(ComparisonWrite(atUs: 0, bytes: live + wrap(A, 0)))
            for i in 1...16 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US / 2, bytes: wrap(A, i))) }
            for i in 17..<150 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US, bytes: wrap(A, i))) }
            w.append(ComparisonWrite(atUs: 150 * FRAME_US, bytes: end))
        case .laterGOPBurst:
            w.append(ComparisonWrite(atUs: 0, bytes: live + wrap(A, 0)))
            for i in 1..<60 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US, bytes: wrap(A, i))) }
            w.append(ComparisonWrite(atUs: 60 * FRAME_US, bytes: (60...76).reduce(Data()) { $0 + wrap(A, $1) }))
            for i in 77..<150 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US, bytes: wrap(A, i))) }
            w.append(ComparisonWrite(atUs: 150 * FRAME_US, bytes: end))
        case .stopWhilePreparing:
            w.append(ComparisonWrite(atUs: 0, bytes: (0...3).reduce(live) { $0 + wrap(A, $1) } + end))
            w.append(ComparisonWrite(atUs: 500_000, bytes: control(.sessionLive(B, generation: 1)) + control(.sessionEnded(B, reason: "stopped-by-mac"))))
            w.append(ComparisonWrite(atUs: 1_000_000, bytes: Data()))
        case .replacement:
            w.append(ComparisonWrite(atUs: 0, bytes: live + wrap(A, 0)))
            for i in 1..<60 { w.append(ComparisonWrite(atUs: UInt64(i) * FRAME_US, bytes: wrap(A, i))) }
            phone.rotation = 0
            phone.generation = 1
            let wrapB = { (i: Int) -> Data in record(B, phone.frame(annexB: hd[i], width: 1280, height: 720)) }
            w.append(ComparisonWrite(atUs: 60 * FRAME_US, bytes: (0...5).reduce(control(.sessionLive(B, generation: 1))) { $0 + wrapB($1) }))
            for i in 6..<60 { w.append(ComparisonWrite(atUs: UInt64(60 + i) * FRAME_US, bytes: wrapB(i))) }
            w.append(ComparisonWrite(atUs: 120 * FRAME_US, bytes: control(.sessionEnded(B, reason: "stopped-by-mac"))))
        }
        w.append(ComparisonWrite(atUs: (w.last?.atUs ?? 0) + 100_000, bytes: control(.shutdown)))
        return w
    }
}

/// One run of one binary: the writes on schedule, then the last `counts` record and the exit line.
private func run(_ exe: String, _ writes: [ComparisonWrite]) throws -> [String: Any] {
    let p = Process()
    p.executableURL = URL(fileURLWithPath: exe)
    p.arguments = ["--max-seconds", String(LIMIT_SECONDS)]
    let inPipe = Pipe(), outPipe = Pipe(), errPipe = Pipe()
    p.standardInput = inPipe; p.standardOutput = outPipe; p.standardError = errPipe
    try p.run()
    var outData = Data(), errData = Data()
    let readers = DispatchGroup()
    readers.enter(); DispatchQueue.global().async { outData = outPipe.fileHandleForReading.readDataToEndOfFile(); readers.leave() }
    readers.enter(); DispatchQueue.global().async { errData = errPipe.fileHandleForReading.readDataToEndOfFile(); readers.leave() }
    let kill = DispatchWorkItem { if p.isRunning { p.terminate() } }
    DispatchQueue.global().asyncAfter(deadline: .now() + .seconds(LIMIT_SECONDS + 5), execute: kill)
    let start = DispatchTime.now().uptimeNanoseconds
    var lateMaxUs: UInt64 = 0
    for w in writes {
        let due = start + w.atUs * 1_000
        let now = DispatchTime.now().uptimeNanoseconds
        if due > now { usleep(UInt32((due - now) / 1_000)) } else { lateMaxUs = max(lateMaxUs, (now - due) / 1_000) }
        if !w.bytes.isEmpty { inPipe.fileHandleForWriting.write(w.bytes) }
    }
    try inPipe.fileHandleForWriting.close()
    p.waitUntilExit()
    kill.cancel()
    readers.wait()
    var dec = RecordDecoder()
    let statuses = try dec.feed(outData).compactMap { try? JSONSerialization.jsonObject(with: $0.body) as? [String: Any] }
    let counts = statuses.last { $0["op"] as? String == "counts" }?["counts"] as? [String: Int] ?? [:]
    let err = String(decoding: errData, as: UTF8.self)
    return [
        "exit": Int(p.terminationStatus),
        "invariantHolds": err.contains("invariant holds"),
        // How late the harness's own writes ran against their schedule: a bound of the instrument,
        // reported beside every reading it shaped.
        "harnessLateMaxUs": Int(lateMaxUs),
        "counts": counts,
    ]
}

@Suite(.serialized) struct ReleaseComparison {
    static let probes: [(String, String)] = (ProcessInfo.processInfo.environment["COMPARE_PROBES"] ?? "")
        .split(separator: ",").compactMap { pair in
            let kv = pair.split(separator: "=", maxSplits: 1).map(String.init)
            return kv.count == 2 ? (kv[0], kv[1]) : nil
        }
    static let out = ProcessInfo.processInfo.environment["COMPARE_OUT"]

    @Test(.enabled(if: probes.count >= 2 && out != nil)) func oldAgainstNewOnTheSameBytes() throws {
        let fullHD = try stream(width: 1920, height: 1080, count: 150, idrAt: [0, 60, 120], profile: kVTProfileLevel_H264_High_AutoLevel).map(\.annexB)
        let hd = try stream(width: 1280, height: 720, count: 60, idrAt: [0], profile: kVTProfileLevel_H264_High_AutoLevel).map(\.annexB)
        var runs: [[String: Any]] = []
        for rep in 0..<REPETITIONS {
            for s in ComparisonScenario.allCases {
                let writes = s.writes(fullHD: fullHD, hd: hd)
                // Interleaved, and the order alternates by repetition, so neither binary always runs first.
                let order = rep % 2 == 0 ? Self.probes : Self.probes.reversed()
                for (name, exe) in order {
                    var r = try run(exe, writes)
                    r["binary"] = name; r["scenario"] = s.rawValue; r["repetition"] = rep
                    #expect(r["exit"] as? Int == 0 && r["invariantHolds"] as? Bool == true, "\(name) \(s.rawValue) #\(rep): \(r)")
                    runs.append(r)
                }
            }
        }
        let doc: [String: Any] = [
            "about": "Defect 177 option A: RELEASE decode probes on identical generated bytes. Tests/WebcamProbeTests/ReleaseComparisonTests.swift. Integers only; nothing identifying.",
            "repetitions": REPETITIONS, "frameUs": Int(FRAME_US),
            "binaries": Dictionary(uniqueKeysWithValues: Self.probes.map { ($0.0, URL(fileURLWithPath: $0.1).lastPathComponent) }),
            "runs": runs,
        ]
        try JSONSerialization.data(withJSONObject: doc, options: [.prettyPrinted, .sortedKeys]).write(to: URL(fileURLWithPath: Self.out!))
        print("release comparison: \(runs.count) runs written to \(Self.out!)")
    }
}
